package com.wandertrace.service;
import com.wandertrace.dto.ContentDtos.*;import com.wandertrace.exception.*;import java.time.*;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class MemoryService {private final JdbcTemplate db;private final TripAccessService access;private final ContentAccessService content;public MemoryService(JdbcTemplate db,TripAccessService access,ContentAccessService content){this.db=db;this.access=access;this.content=content;}public List<Memory> list(UUID user,UUID destination){access.requireView(user,content.tripForDestination(destination));return db.queryForList("select * from memories where destination_id=? order by memory_date desc",destination).stream().map(this::map).toList();}@Transactional public Memory create(UUID user,UUID destination,MemoryRequest r){access.requireEdit(user,content.tripForDestination(destination));UUID id=UUID.randomUUID();validateCover(id,r.coverMediaId());db.update("insert into memories(id,destination_id,title,subtitle,story,memory_date,visibility,cover_media_id) values(?,?,?,?,?,?,?,?)",id,destination,r.title(),r.subtitle(),r.story(),r.memoryDate(),r.visibility(),r.coverMediaId());return get(user,id); }public Memory get(UUID user,UUID id){access.requireView(user,content.tripForMemory(id));return map(one(id));}@Transactional public Memory update(UUID user,UUID id,MemoryRequest r){access.requireEdit(user,content.tripForMemory(id));validateCover(id,r.coverMediaId());db.update("update memories set title=?,subtitle=?,story=?,memory_date=?,visibility=?,cover_media_id=?,updated_at=now() where id=?",r.title(),r.subtitle(),r.story(),r.memoryDate(),r.visibility(),r.coverMediaId(),id);return get(user,id);}@Transactional public void delete(UUID user,UUID id){access.requireEdit(user,content.tripForMemory(id));db.update("delete from memories where id=?",id);}private void validateCover(UUID memory,UUID cover){if(cover==null)return;var r=db.queryForList("select id from media where id=? and memory_id=?",cover,memory);if(r.isEmpty())throw new IllegalArgumentException("Cover media must belong to this memory");}private Map<String,Object>one(UUID id){var r=db.queryForList("select * from memories where id=?",id);if(r.isEmpty())throw new NotFoundException("Memory not found");return r.getFirst();}private Memory map(Map<String,Object>r){return new Memory((UUID)r.get("id"),(UUID)r.get("destination_id"),(String)r.get("title"),(String)r.get("subtitle"),(String)r.get("story"),date(r.get("memory_date")),(String)r.get("visibility"),(UUID)r.get("cover_media_id"),instant(r.get("created_at")),instant(r.get("updated_at")));}private LocalDate date(Object x){return x instanceof LocalDate d?d:((java.sql.Date)x).toLocalDate();}private Instant instant(Object x){return ((java.sql.Timestamp)x).toInstant();}}
